const SF_SAVE_SCHEMA=4;
const SF_ACTIVE_KEY='sf_active_battle_v4';
const SF_RECOVERY_KEY='sf_recovery_battle_v4';
const SF_EDITOR_SAVES='sf_manual_saves_v4';
