// ---- Preferences / migration ------------------------------------------------
Object.assign(DEFAULT_PREFS,{reducedMotion:false,reducedFlashing:false,highContrast:false,visualAudio:false,leftHanded:false,hudPreset:'Standard',textSize:'Normal',doctrine:'Balanced'});
for(const [k,v] of Object.entries(DEFAULT_PREFS))if(prefs[k]===undefined)prefs[k]=v;
stats.operations=stats.operations||{};stats.chronicles=Array.isArray(stats.chronicles)?stats.chronicles:[];stats.medals=Array.isArray(stats.medals)?stats.medals:[];
prefs.watchlist=Array.isArray(prefs.watchlist)?prefs.watchlist:[];

function sfSafeParse(raw,fallback=null){try{return JSON.parse(raw)}catch(e){return fallback}}
function sfStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){console.warn('Storage write failed',key,e);return false}}
function sfLoad(key){try{return sfSafeParse(localStorage.getItem(key),null)}catch(e){return null}}
function sfDelete(key){try{localStorage.removeItem(key)}catch(e){}}
function sfMeta(){return{schema:SF_SAVE_SCHEMA,build:SF_BUILD,updatedAt:Date.now()}}

// ---- Startup / branding -----------------------------------------------------
function visualAudioCue(text,kind='ui'){
  if(!prefs.visualAudio||!text)return;
  let el=$('#visualAudioCue');
  if(!el){el=document.createElement('div');el.id='visualAudioCue';el.className='visualAudio';$('#gameScreen')?.appendChild(el)}
  el.textContent=text;el.dataset.kind=kind;el.classList.add('show');clearTimeout(visualAudioCue.t);visualAudioCue.t=setTimeout(()=>el.classList.remove('show'),1100);
}
function phantomFlexSting(){if(!prefs.sound)return;ensureAudio();tone(92,.34,'sine',.055,0,'ui',148);tone(220,.21,'triangle',.032,.12,'ui',330);tone(440,.16,'sine',.021,.27,'ui',660)}
function titleSting(){if(!prefs.sound)return;ensureAudio();[196,293.66,392,587.33].forEach((f,i)=>tone(f,.45,'triangle',.027,i*.08,'music'));}
function initLaunchSequence(){
  const seq=$('#launchSequence'),tap=$('#tapToStart');if(!seq||!tap)return;
  let titleShown=false,entered=false;
  const showTitle=()=>{if(titleShown)return;titleShown=true;seq.classList.add('title');phantomFlexSting();setTimeout(titleSting,260)};
  const enter=()=>{if(entered)return;entered=true;ensureAudio();soundEvent('open');seq.classList.add('done');sessionStorage.setItem('sf_session_started','1');setTimeout(()=>{seq.style.display='none';syncMusic()},520)};
  seq.addEventListener('pointerdown',e=>{if(!titleShown){e.preventDefault();showTitle()}});
  tap.onclick=e=>{e.stopPropagation();enter()};
  setTimeout(showTitle,760);
}

// ---- PWA shell / safe updates -----------------------------------------------
function requestPWAUpdateActivation(){if(!sfWaitingWorker)return false;if(game.running){if(game.events)pushEvent('Update ready — finish or leave this battle to install it','good',8);return false}sfReloadForUpdate=true;sfWaitingWorker.postMessage('SKIP_WAITING');return true}
function initPWA(){
  if(!('serviceWorker'in navigator)||location.protocol==='file:'||location.protocol==='about:')return;
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(sfReloadForUpdate&&!game.running)location.reload()});
  navigator.serviceWorker.register('./service-worker.js').then(reg=>{
    if(reg.waiting){sfWaitingWorker=reg.waiting;requestPWAUpdateActivation()}
    reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller){sfWaitingWorker=w;if(game.running){pushEvent('Sovereign Front update ready — it will wait for this campaign','good',8)}else requestPWAUpdateActivation()}})});
  }).catch(e=>console.warn('PWA registration unavailable',e));
}

