const legacyActiveRules=activeRules;
activeRules=function(modeId=prefs.mode){
  if(modeId==='spectator'){const map=MAPS[prefs.map]||MAPS.world;return{bots:prefs.map==='world'?72:48,startTroops:760,growth:1,gameSpeed:1,timeLimit:0,victory:100,navalRange:Math.max(18,Math.round(map.naval*110)),attackSpeed:1,neutralCost:2.85,spawnRadius:2,peacefulStart:10,aiBias:'Balanced',stats:false,sandbox:false,spectator:true}}
  if(modeId==='operation'&&pendingDeployment?.operationId){const o=OPERATIONS[pendingDeployment.operationId];return{...o.rules,stats:false,sandbox:false,operation:true,objectiveSpec:{...o.objectiveSpec}}}
  return legacyActiveRules(modeId);
};

// ---- Premium deployment briefing -------------------------------------------
function deploymentSeed(){return((Date.now()&0xffffffff)^((performance.now()*1000)|0)^0x5f3759df)>>>0}
function briefingModeName(modeId,opts={}){return modeId==='operation'?OPERATIONS[opts.operationId]?.name||'Operation':MODES[modeId]?.name||'Classic'}
function openDeploymentBriefing(modeId=prefs.mode,opts={}){
  const seed=opts.seed??deploymentSeed();pendingDeployment={modeId,seed,...opts};
  const mapId=modeId==='operation'?OPERATIONS[opts.operationId].theater:prefs.map,diff=modeId==='operation'?OPERATIONS[opts.operationId].difficulty:prefs.difficulty,map=MAPS[mapId],rules=modeId==='operation'?OPERATIONS[opts.operationId].rules:activeRules(modeId),title=briefingModeName(modeId,opts);
  $('#briefingTitle').textContent=title;
  const objective=modeId==='operation'?OPERATIONS[opts.operationId].objective:`Control ${rules.victory}% of playable land or become the last surviving nation.`;
  $('#briefingBody').innerHTML=`<div class="briefGrid"><div class="briefFact"><span>THEATER</span><b>${escapeHTML(map.name)}</b></div><div class="briefFact"><span>DIFFICULTY</span><b>${escapeHTML(diff)}</b></div><div class="briefFact"><span>DOCTRINE</span><b>${escapeHTML(prefs.doctrine||'Balanced')}</b></div><div class="briefFact"><span>STARTING POWERS</span><b>${Math.round(rules.bots)+(rules.spectator?0:1)}</b></div><div class="briefFact"><span>NAVAL RANGE</span><b>${Math.round(rules.navalRange)} cells</b></div><div class="briefFact"><span>SEED</span><b>${seed.toString(16).toUpperCase()}</b></div></div><div class="briefObjective"><span>PRIMARY OBJECTIVE</span><b>${escapeHTML(objective)}</b></div>`;
  closeAllModals();$('#briefingModal').classList.add('open');soundEvent('open');
}
function confirmDeployment(){const p=pendingDeployment;if(!p)return;$('#briefingModal').classList.remove('open');if(p.modeId==='operation'){const o=OPERATIONS[p.operationId];prefs.map=o.theater;prefs.difficulty=o.difficulty;savePrefs()}startGame(p.modeId,{seed:p.seed,operationId:p.operationId||null});pendingDeployment=null}

// ---- Accessibility / layout -------------------------------------------------
function applyMajorPreferences(){
  document.documentElement.classList.toggle('reducedMotion',!!prefs.reducedMotion);
  document.documentElement.classList.toggle('highContrast',!!prefs.highContrast);
  document.documentElement.classList.toggle('leftHanded',!!prefs.leftHanded);
  document.documentElement.classList.toggle('hudCompact',prefs.hudPreset==='Compact');
  document.documentElement.classList.toggle('hudTactical',prefs.hudPreset==='Tactical');
  const ts={Small:.9,Normal:1,Large:1.1,'Extra Large':1.2}[prefs.textSize]||1;document.documentElement.style.setProperty('--uiTextScale',ts);
}
function bindMajorSettings(){
  const tog=(id,key)=>{const e=$(id);if(!e)return;e.classList.toggle('on',!!prefs[key]);e.onclick=()=>{clickFx();prefs[key]=!prefs[key];savePrefs();applyMajorPreferences();renderToggles();if(game.running)game.dirty=true}};
  [['#reducedMotionToggle','reducedMotion'],['#reducedFlashingToggle','reducedFlashing'],['#highContrastToggle','highContrast'],['#visualAudioToggle','visualAudio'],['#leftHandedToggle','leftHanded']].forEach(x=>tog(...x));
  const hp=$('#hudPresetSelect'),ts=$('#textSizeSelect'),doc=$('#doctrineSelect');
  if(hp){hp.value=prefs.hudPreset;hp.onchange=e=>{prefs.hudPreset=e.target.value;savePrefs();applyMajorPreferences();soundEvent('tap')}}
  if(ts){ts.value=prefs.textSize;ts.onchange=e=>{prefs.textSize=e.target.value;savePrefs();applyMajorPreferences();soundEvent('tap')}}
  if(doc){doc.value=prefs.doctrine||'Balanced';doc.onchange=e=>{prefs.doctrine=e.target.value;savePrefs();soundEvent('tap')}}
}

// ---- Menu / entry point bindings --------------------------------------------
function bindMajorMenu(){
  $('#playBtn').onclick=()=>{clickFx();openDeploymentBriefing(prefs.mode)};
  $('#modePlayBtn').onclick=()=>{clickFx();openDeploymentBriefing(prefs.mode)};
  $('#briefingCancel').onclick=()=>{clickFx();$('#briefingModal').classList.remove('open');pendingDeployment=null};
  $('#briefingDeploy').onclick=()=>{clickFx();confirmDeployment()};
  $('#sandboxMenuBtn').onclick=()=>{clickFx();prefs.mode='sandbox';savePrefs();renderModeButtons();updateCustomControls();openModal('modes')};
  $('#spectatorMenuBtn').onclick=()=>{clickFx();openDeploymentBriefing('spectator')};
  $('#warOverviewBtn').onclick=()=>{clickFx();renderWarOverview();openModal('war')};
  $('#diplomacyBtn').onclick=()=>{clickFx();renderDiplomacy();openModal('diplomacy')};
  $('#pauseSaveBtn').onclick=()=>{clickFx();saveActiveBattle('manual',true)};
  $('#reportBtn').onclick=()=>{clickFx();renderCampaignReport();openModal('report')};
  $('#continueCampaignBtn').onclick=()=>{clickFx();restoreActiveBattle()};
  $('#nationSearchInput')?.addEventListener('input',renderDiplomacy);
  $$('.reportTab').forEach(b=>b.onclick=()=>{soundEvent('tap');$$('.reportTab').forEach(x=>x.classList.toggle('sel',x===b));for(const id of ['summary','chronicle','timeline'])$('#report'+id[0].toUpperCase()+id.slice(1)).hidden=id!==b.dataset.reportTab;if(b.dataset.reportTab==='timeline')drawTimelineReport()});
}

function updateContinueCampaignCard(){
  const b=$('#continueCampaignBtn');if(!b)return;const s=getBestRecoverySave();if(!s){b.hidden=true;return}b.hidden=false;const sum=s.summary||{};$('#continueNation').textContent=sum.nation||'Recover Battle';$('#continueMeta').textContent=`${sum.map||'Unknown'} · ${sum.mode||'Campaign'} · ${sum.difficulty||'Normal'}`;$('#continueStats').textContent=`${sum.rank?'#'+sum.rank:'ACTIVE'} · ${(sum.land||0).toFixed(1)}% · ${timeFmt(sum.time||0)}`;b.querySelector('.continueEyebrow').textContent=s.recovery?'RECOVER BATTLE':'CONTINUE CAMPAIGN';
}

