function encodeOwnerRLE(arr){if(!arr?.length)return'';const out=[];let v=arr[0],n=1;for(let i=1;i<arr.length;i++){if(arr[i]===v)n++;else{out.push((v+2).toString(36)+':'+n.toString(36));v=arr[i];n=1}}out.push((v+2).toString(36)+':'+n.toString(36));return out.join(',')}
function decodeOwnerRLE(str,len){if(typeof str!=='string'||!str)return null;const a=new Int16Array(len);let pos=0;for(const token of str.split(',')){const [vs,ns]=token.split(':');const v=parseInt(vs,36)-2,n=parseInt(ns,36);if(!Number.isFinite(v)||!Number.isFinite(n)||n<1||pos+n>len)return null;a.fill(v,pos,pos+n);pos+=n}return pos===len?a:null}
function serialPlayer(p){return{id:p.id,name:p.name,avatar:p.avatar,avatarImage:p.avatarImage||'',color:p.color,balance:p.balance,alive:p.alive,behavior:p.behavior,baseBehavior:p.baseBehavior,think:p.think,elims:p.elims||0,recentLoss:p.recentLoss||0,recentGain:p.recentGain||0,lastAttacker:p.lastAttacker??-1,lastAttackedAt:p.lastAttackedAt??-99,aiCursor:p.aiCursor||0,capital:p.capital??-1,capitalRelocateAt:p.capitalRelocateAt||0,capitalLosses:p.capitalLosses||0,stability:p.stability??1,warExhaustion:p.warExhaustion||0,doctrine:p.doctrine||'Balanced',traits:p.traits||null,strategicGoal:p.strategicGoal||null,peakCells:p.peakCells||0,warsWon:p.warsWon||0,warsLost:p.warsLost||0,capitalsCaptured:p.capitalsCaptured||0,navalConfidence:p.navalConfidence??.5,freezeAI:!!p.freezeAI,supply:p.supply??1,suppliedCells:p.suppliedCells||0,unsuppliedCells:p.unsuppliedCells||0}}
function restorePlayer(x){return{...x,cells:new Set(),border:new Set(),coast:new Set(),components:new Map(),attacks:0}}
function serializeAttack(a){return{attacker:a.attacker,defender:a.defender,army:a.army,initialArmy:a.initialArmy,frontier:[...(a.frontier||[])],acc:a.acc||0,dead:!!a.dead,source:a.source??-1,targetCell:a.targetCell??-1,captured:a.captured||0,reason:a.reason||''}}
function serializeNaval(n){return{attacker:n.attacker,defender:n.defender,army:n.army,from:n.from,to:n.to,targetCell:n.targetCell,progress:n.progress,duration:n.duration,initialArmy:n.initialArmy}}
