    Object.assign(game,{running:true,paused:false,over:false,winner:false,human:s.human??0,spectator:!!s.spectator,spawnLeft:0,lastCountdown:0,spawned:true,time:+s.time||0,attacks:[],navals:[],fx:[],events:[],contacts:[],contactDirty:true,labels:[],captured:s.counters?.captured||0,eliminations:s.counters?.eliminations||0,attacksLaunched:s.counters?.attacksLaunched||0,navalsLaunched:s.counters?.navalsLaunched||0,navalsSucceeded:s.counters?.navalsSucceeded||0,maxHumanPct:s.counters?.maxHumanPct||0,lastLeader:s.counters?.lastLeader??-1,announcedLeader:s.counters?.announcedLeader??-1,leaderSince:s.counters?.leaderSince||0,lastHeavyWarning:0,simAcc:0,hudAcc:0,contactAcc:0,miniAcc:0,labelAcc:0,eventAcc:0,borderDirty:true,borderLast:0,pendingAttack:null,tutorialActive:false,tutorialStage:0,tutorialTimer:0,aiFrozen:false,sandboxEditing:false,sandboxPaint:null,sandboxSelected:1,sandboxIntel:false,inspected:-1,lastTarget:-1,operationId:s.operationId||null,objective:s.objective||null,diplomacy:s.diplomacy||{},wars:Array.isArray(s.wars)?s.wars:[],chronicle:Array.isArray(s.chronicle)?s.chronicle:[],timeline:Array.isArray(s.timeline)?s.timeline:[],globalWar:!!s.globalWar,globalWarStartedAt:s.globalWarStartedAt||0,watchlist:new Set(s.watchlist||[]),cities:Array.isArray(s.cities)?s.cities:[],supplyAcc:0,supplyReady:false,lastSupplyWarning:-99});
    game.warSeq=Math.max(0,...(game.wars||[]).map(w=>Number.isFinite(+w.id)?+w.id:0));game.lastChronicleLeader=game.lastLeader??-1;
    game.cam={zoom:s.camera?.zoom||1,panX:s.camera?.panX||0,panY:s.camera?.panY||0,vx:0,vy:0};game.attackPct=clamp(+s.attackPct||50,10,100);$('#attackSlider').value=game.attackPct;
    world.width=game.GW;world.height=game.GH;const br=borderResolution();borderWorld.width=game.GW*br;borderWorld.height=game.GH*br;generateMap();analyzeTopology();const own=decodeOwnerRLE(s.ownerRLE,game.GW*game.GH);if(!own)throw new Error('Invalid ownership payload');game.owner=own;game.players=s.players.map(restorePlayer);rebuildPlayersFromOwner();game.attacks=(s.attacks||[]).map(a=>({...a,frontier:[...(a.frontier||[])],seen:new Set(a.frontier||[]),dead:false}));game.navals=(s.navals||[]).map(n=>({...n}));for(const a of game.attacks)if(game.players[a.attacker])game.players[a.attacker].attacks++;
    rebuildCityIndex();computeSupplyState();rebuildAllBorders();rebuildContacts();paintWholeWorld();redrawBorders();computeLabels();resizeCanvas();updateHUD(true);updateLeaderboard(true);updateMinimap();renderEventFeed();$('#pauseOverlay').classList.remove('open');$('#resultOverlay').classList.remove('open');$('#spawnOverlay').style.display='none';document.documentElement.classList.toggle('sandboxActive',!!game.rules.sandbox);applyLiveSettings();applyMajorPreferences();updateAttackControls();syncMusic();game.lastTS=performance.now();game.lastRenderTS=game.lastTS;if(game.rafId)cancelAnimationFrame(game.rafId);game.rafId=requestAnimationFrame(loop);pushEvent(s.recovery?'Recovered battle state':'Campaign resumed','good',5);recordChronicle('resume',s.recovery?'Battle recovered after interruption.':'Command resumed the campaign.',{});return true
