// Periodic and lifecycle recovery. Periodic writes are infrequent to avoid jank.
setInterval(()=>{if(game.running&&!game.paused&&!game.over&&game.spawned)saveActiveBattle('periodic')},18000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.running&&!game.over)saveActiveBattle('background')});
window.addEventListener('pagehide',()=>{if(game.running&&!game.over)saveActiveBattle('pagehide')});
const legacyPauseGame=pauseGame;pauseGame=function(auto=false){legacyPauseGame(auto);if(game.running&&!game.over)saveActiveBattle(auto?'background':'pause')};
const legacyEndToMenu=endToMenu;endToMenu=function(){if(game.running&&!game.over&&game.spawned)saveActiveBattle('menu');legacyEndToMenu();updateContinueCampaignCard();setTimeout(requestPWAUpdateActivation,50)};

