// STRATEGIC GEOGRAPHY: TERRAIN, CAPITALS, CITIES, DOCTRINES
// =============================================================================
const TERRAIN={WATER:0,PLAINS:1,FOREST:2,MOUNTAIN:3,DESERT:4,TUNDRA:5};
const TERRAIN_NAME=['Water','Plains','Forest','Mountains','Desert','Tundra'];
const CITY_POOLS={
 europe:['Asterholm','Bravena','Caldor','Dunmar','Elsen','Falken','Galenport','Istren','Karsfeld','Lunara','Maribor','Norgrad','Orvale','Ravnik','Solenne','Tarnow','Valen','Westhaven','Zorya','Arden'],
 asia:['Akari','Bayan','Caspin','Daryun','Eshar','Harin','Jinora','Kesh','Laitan','Miran','Naryn','Ordos','Qamar','Rashan','Sairu','Tenzin','Ulanor','Varan','Yorin','Zarin'],
 oceania:['Aroa','Bellan','Coral Bay','Darwin Reach','Elaru','Fenton','Gale Point','Haven Reef','Isla Nova','Koru','Luma','Marakai','Naru','Opal Coast','Port Sable','Ranoa','Tala','Vela','Waiora','Zephyr Bay'],
 northAmerica:['Arbor','Briar City','Cedar Point','Dakota Reach','Evermont','Frontier','Granite Bay','Hudson Vale','Ironwood','Juniper','Kingsport','Liberty','Monroe','Northgate','Oak Ridge','Prairie City','Redstone','Silver Lake','Union','Westport'],
 southAmerica:['Altura','Brisa','Cordela','Dorada','Estrella','Faro','Gran Valle','Horizonte','Ibera','Jardim','Lagoa','Monte Azul','Nueva Sol','Oro Verde','Pampas','Rio Claro','Sierra','Trinidad','Verde','Zafira'],
 world:['Aster','Boreal','Crownport','Dawn','Equinox','Frontier','Grand Harbor','Highland','Iron Gate','Junction','Keystone','Liberty','Meridian','Northstar','Oceanic','Polaris','Riverhold','Summit','Unity','Vanguard','Westreach','Zenith']
};
function sfHash(x,y,s=0){let h=(Math.imul((x|0)^0x9e3779b9,374761393)+Math.imul((y|0)^s,668265263))|0;h=(h^(h>>>13));h=Math.imul(h,1274126177);return((h^(h>>>16))>>>0)/4294967295}
function terrainAt(x,y){
  const n=sfHash(x,y,(game.mapId.length*811)^0x51f15e),ny=y/Math.max(1,game.GH-1),nx=x/Math.max(1,game.GW-1);
  if(game.mapId==='world'){if(ny<.10||ny>.91)return n>.42?TERRAIN.TUNDRA:TERRAIN.PLAINS;if(ny>.36&&ny<.66&&n>.76)return TERRAIN.DESERT}
  if(game.mapId==='asia'){if(ny<.14&&n>.36)return TERRAIN.TUNDRA;if(ny>.42&&ny<.72&&nx<.62&&n>.69)return TERRAIN.DESERT}
  if(game.mapId==='northAmerica'&&ny<.18&&n>.38)return TERRAIN.TUNDRA;
  if(game.mapId==='southAmerica'&&ny>.82&&n>.42)return TERRAIN.TUNDRA;
  if(game.mapId==='oceania'&&ny>.42&&nx<.7&&n>.58)return TERRAIN.DESERT;
  const ridge=sfHash((x/5)|0,(y/4)|0,game.mapId.charCodeAt(0)*97);if(ridge>.885)return TERRAIN.MOUNTAIN;if(n>.66)return TERRAIN.FOREST;return TERRAIN.PLAINS
}
const legacyGenerateMap=generateMap;
generateMap=function(){legacyGenerateMap();for(let i=0;i<game.owner.length;i++)if(game.owner[i]!==WATER)game.terrain[i]=terrainAt(i%game.GW,(i/game.GW)|0)};
analyzeTopology=function(){const N=game.owner.length,ids=new Int16Array(N);ids.fill(-1);const q=new Int32Array(N);game.components=[];game.coastCells=[];let cid=0;for(let s=0;s<N;s++){if(game.terrain[s]===TERRAIN.WATER||ids[s]>=0)continue;let head=0,tail=0,size=0,sx=0,sy=0;const coasts=[];ids[s]=cid;q[tail++]=s;while(head<tail){const i=q[head++],x=i%game.GW,y=(i/game.GW)|0;size++;sx+=x;sy+=y;let coast=false;const ns=[];if(x>0)ns.push(i-1);else coast=true;if(x<game.GW-1)ns.push(i+1);else coast=true;if(y>0)ns.push(i-game.GW);else coast=true;if(y<game.GH-1)ns.push(i+game.GW);else coast=true;for(const n of ns){if(game.terrain[n]===TERRAIN.WATER)coast=true;else if(ids[n]<0){ids[n]=cid;q[tail++]=n}}if(coast){coasts.push(i);game.coastCells.push(i)}}game.components.push({id:cid,size,coasts,cx:sx/size,cy:sy/size});cid++}game.componentId=ids};
function shadeTerrain(rgb,t){let [r,g,b]=rgb;if(t===TERRAIN.FOREST){r*=.88;g=Math.min(255,g*.94+8);b*=.88}else if(t===TERRAIN.MOUNTAIN){const m=(r+g+b)/3;r=r*.72+m*.18;g=g*.72+m*.18;b=b*.72+m*.20}else if(t===TERRAIN.DESERT){r=Math.min(255,r*1.03+10);g=Math.min(255,g*.96+6);b*=.82}else if(t===TERRAIN.TUNDRA){r=Math.min(255,r*.92+18);g=Math.min(255,g*.95+18);b=Math.min(255,b*1.02+18)}return[r|0,g|0,b|0]}
paintCell=function(i){const x=i%game.GW,y=(i/game.GW)|0,o=game.owner[i];let rgb;if(o===WATER){const n=(x*17+y*11)%31;rgb=[26+(n<4?3:0),72+(n<6?4:0),96+(n<8?5:0)]}else{rgb=o===NEUTRAL?[128,137,127]:hexToRgb(game.players[o]?.color||'#7b8990');rgb=shadeTerrain(rgb,game.terrain[i])}wctx.fillStyle=`rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;wctx.fillRect(x,y,1,1);game.dirty=true;game.borderDirty=true};
paintWholeWorld=function(){const img=wctx.createImageData(game.GW,game.GH);for(let i=0;i<game.owner.length;i++){const p=i*4,o=game.owner[i],x=i%game.GW,y=(i/game.GW)|0;let c;if(o===WATER){const n=(x*17+y*11)%31;c=[25+(n<4?3:0),70+(n<6?5:0),96+(n<8?6:0)]}else{c=o===NEUTRAL?[130,139,128]:hexToRgb(game.players[o]?.color||'#7b8990');c=shadeTerrain(c,game.terrain[i])}img.data[p]=c[0];img.data[p+1]=c[1];img.data[p+2]=c[2];img.data[p+3]=255}wctx.putImageData(img,0,0);game.borderDirty=true;game.dirty=true};

function generateStrategicCities(){
  const pool=CITY_POOLS[game.mapId]||CITY_POOLS.world,count=game.mapId==='world'?28:game.modeId==='big'?22:game.modeId==='quick'?8:14,candidates=[];
  const stride=Math.max(2,Math.floor(Math.sqrt(game.landCount/Math.max(1,count))/2));
  for(let y=stride;y<game.GH-stride;y+=stride)for(let x=stride;x<game.GW-stride;x+=stride){const i=y*game.GW+x;if(game.owner[i]!==NEUTRAL)continue;let land=0;for(let yy=-2;yy<=2;yy++)for(let xx=-2;xx<=2;xx++){const j=(y+yy)*game.GW+(x+xx);if(game.owner[j]!==WATER)land++}if(land<20)continue;const score=land+sfHash(x,y,game.GW)*8-(game.terrain[i]===TERRAIN.MOUNTAIN?2:0);candidates.push({cell:i,score})}
  candidates.sort((a,b)=>b.score-a.score);game.cities=[];const minDist=Math.max(7,Math.sqrt(game.landCount/Math.max(1,count))*1.25);for(const c of candidates){if(game.cities.length>=count)break;const x=c.cell%game.GW,y=(c.cell/game.GW)|0;if(game.cities.some(z=>{const zx=z.cell%game.GW,zy=(z.cell/game.GW)|0;return Math.hypot(zx-x,zy-y)<minDist}))continue;game.cities.push({id:game.cities.length,cell:c.cell,name:pool[game.cities.length%pool.length],owner:NEUTRAL,captures:0})}rebuildCityIndex()
}
function rebuildCityIndex(){game.cityByCell=new Map();for(const c of game.cities||[]){c.owner=game.owner?.[c.cell]??c.owner??NEUTRAL;game.cityByCell.set(c.cell,c)}}
function playerCityCount(pid){let n=0;for(const c of game.cities||[])if(game.owner[c.cell]===pid)n++;return n}
function terrainDefense(t){return t===TERRAIN.MOUNTAIN?1.36:t===TERRAIN.FOREST?1.14:t===TERRAIN.DESERT?.94:t===TERRAIN.TUNDRA?1.06:1}
const legacyCellDefenseCost=cellDefenseCost;
cellDefenseCost=function(defender,cell){let cost=legacyCellDefenseCost(defender,cell)*terrainDefense(game.terrain[cell]);if(defender>=0){const p=game.players[defender];if(p?.capital===cell)cost*=1.58;if(game.cityByCell?.has(cell))cost*=1.18;const doc=p?.doctrine;if(doc==='Fortress')cost*=1.07}return clamp(cost,3,130)};
const legacyGrowthRate=growthRate;
growthRate=function(p){let base=legacyGrowthRate(p);if(!p?.alive)return base;const cities=playerCityCount(p.id);base*=1+Math.min(.14,cities*.012);if(p.capital<0)base*=.82;base*=clamp(.72+(p.stability??1)*.28,.62,1.05);if(p.doctrine==='Rapid Expansion')base*=1.025;else if(p.doctrine==='Calculated')base*=1.012;return base};

// Supply is intentionally readable rather than simulation-heavy. Every few seconds we
// classify each contiguous national region. A capital or owned strategic city is a supply
// hub; disconnected possessions without a hub suffer modest economic/defensive friction.
function computeSupplyState(){
  const N=game.owner?.length||0;if(!N||!game.players?.length)return;
  if(!game.supplyStamp||game.supplyStamp.length!==N){game.supplyStamp=new Uint32Array(N);game.supplyQueue=new Int32Array(N);game.supplyMask=new Uint8Array(N);game.supplyGen=0}
  game.supplyGen=(game.supplyGen+1)>>>0;if(!game.supplyGen){game.supplyStamp.fill(0);game.supplyGen=1}const gen=game.supplyGen,stamp=game.supplyStamp,q=game.supplyQueue,mask=game.supplyMask;mask.fill(0);
  for(const p of game.players){p.suppliedCells=0;p.unsuppliedCells=0;p.supplyComponents=0}
  for(let s=0;s<N;s++){const pid=game.owner[s];if(pid<0||stamp[s]===gen)continue;const p=game.players[pid];if(!p)continue;let head=0,tail=0,hub=false;stamp[s]=gen;q[tail++]=s;
    while(head<tail){const i=q[head++];if(i===p.capital||game.cityByCell?.has(i))hub=true;const x=i%game.GW,y=(i/game.GW)|0;let n;if(x>0){n=i-1;if(game.owner[n]===pid&&stamp[n]!==gen){stamp[n]=gen;q[tail++]=n}}if(x<game.GW-1){n=i+1;if(game.owner[n]===pid&&stamp[n]!==gen){stamp[n]=gen;q[tail++]=n}}if(y>0){n=i-game.GW;if(game.owner[n]===pid&&stamp[n]!==gen){stamp[n]=gen;q[tail++]=n}}if(y<game.GH-1){n=i+game.GW;if(game.owner[n]===pid&&stamp[n]!==gen){stamp[n]=gen;q[tail++]=n}}}
    if(hub){p.suppliedCells+=tail;p.supplyComponents++;for(let k=0;k<tail;k++)mask[q[k]]=1}else p.unsuppliedCells+=tail;
  }
  for(const p of game.players){if(!p.cells?.size){p.supply=0;continue}p.supply=clamp(p.suppliedCells/p.cells.size,0,1)}game.supplyReady=true;
}
const sfGrowthWithStrategicState=growthRate;
growthRate=function(p){let base=sfGrowthWithStrategicState(p);if(!p?.alive)return base;const supply=p.supply??1;base*=.72+.28*clamp(supply,0,1);return base};
const sfDefenseWithTerrain=cellDefenseCost;
cellDefenseCost=function(defender,cell){let cost=sfDefenseWithTerrain(defender,cell);if(defender>=0&&game.supplyReady&&game.supplyMask?.[cell]===0)cost*=.84;return cost};
function supplyLabel(p){const s=p?.supply??1;return s>=.93?'SECURE':s>=.72?'STRETCHED':s>=.48?'STRAINED':'DISRUPTED'}

function doctrineForBehavior(b){return b==='navigator'?'Naval Command':b==='defensive'?'Fortress':b==='expansionist'?'Rapid Expansion':b==='opportunist'?'Calculated':'Balanced'}
function traitsForBehavior(b){const base={aggression:.5,caution:.5,diplomacy:.5,loyalty:.5,vengeance:.45,naval:.4,ambition:.55};if(b==='aggressive')Object.assign(base,{aggression:.82,caution:.28,vengeance:.68,ambition:.72});if(b==='defensive')Object.assign(base,{aggression:.32,caution:.82,loyalty:.64});if(b==='opportunist')Object.assign(base,{aggression:.55,caution:.58,diplomacy:.46,ambition:.68});if(b==='expansionist')Object.assign(base,{aggression:.48,caution:.44,ambition:.82});if(b==='navigator')Object.assign(base,{naval:.9,aggression:.52,caution:.47});for(const k in base)base[k]=clamp(base[k]+(gRandom()-.5)*.16,.08,.95);return base}

createPlayers=function(){
  const spectator=!!game.rules.spectator,count=clamp(Math.round(game.rules.bots)+(spectator?0:1),2,101),base=['aggressive','opportunist','defensive','expansionist','navigator'],bias=game.rules.aiBias||'Balanced',weights=bias==='Aggressive'?['aggressive','aggressive','opportunist','expansionist','navigator']:bias==='Defensive'?['defensive','defensive','opportunist','navigator','expansionist']:bias==='Naval'?['navigator','navigator','opportunist','aggressive','expansionist']:bias==='Expansion'?['expansionist','expansionist','navigator','opportunist','aggressive']:base,names=new Set();
  if(!spectator)names.add(prefs.name||'Player');function botName(){for(let q=0;q<80;q++){let n=gRandom()<.20?NATION_WORDS[(gRandom()*NATION_WORDS.length)|0]:BOT_FIRST[(gRandom()*BOT_FIRST.length)|0]+' '+BOT_LAST[(gRandom()*BOT_LAST.length)|0];if(!names.has(n)){names.add(n);return n}}return 'State '+(names.size+1)}
  game.players=[];for(let i=0;i<count;i++){const human=!spectator&&i===0,behavior=human?'human':weights[(gRandom()*weights.length)|0],avatar=human?(prefs.avatarImage?'custom':prefs.avatar):AVATARS[(gRandom()*AVATARS.length)|0],doc=human?(prefs.doctrine||'Balanced'):doctrineForBehavior(behavior);game.players.push({id:i,name:human?(prefs.name||'Player'):botName(),avatar,avatarImage:human?prefs.avatarImage:'',color:human?prefs.color:'#888',balance:game.rules.startTroops,cells:new Set(),border:new Set(),coast:new Set(),components:new Map(),alive:true,behavior,baseBehavior:human?'opportunist':behavior,think:gRand(1.1,.2),attacks:0,elims:0,recentLoss:0,recentGain:0,lastAttacker:-1,lastAttackedAt:-99,aiCursor:(i*37)%997,capital:-1,capitalRelocateAt:0,capitalLosses:0,stability:1,warExhaustion:0,doctrine:doc,traits:traitsForBehavior(human?'opportunist':behavior),strategicGoal:null,peakCells:0,warsWon:0,warsLost:0,capitalsCaptured:0,navalConfidence:behavior==='navigator'?.75:.45,freezeAI:false,supply:1,suppliedCells:0,unsuppliedCells:0})}
};
const legacyClaimSpawn=claimSpawn;
claimSpawn=function(pid,center,r=game.rules?.spawnRadius||2){const ok=legacyClaimSpawn(pid,center,r);if(ok){const p=game.players[pid];if(p&&p.capital<0&&game.owner[center]===pid){p.capital=center;p.stability=1;if(pid===game.human){recordChronicle('capital',`${p.name} established its capital.`,{nation:pid,cell:center});visualAudioCue('Capital established','battle')}}}return ok};
spawnBots=function(){game.spawnPoints=[];const scale=Math.max(1,Math.max(game.GW,game.GH)/520),spacing=(game.map.spawnSpace||8)*scale*(game.modeId==='big'?.92:game.modeId==='quick'?1.03:1),start=game.human<0?0:1;for(let i=start;i<game.players.length;i++){let s=findSpawn(spacing);if(s<0)s=findSpawn(spacing*.62);if(s>=0)claimSpawn(i,s,game.rules.spawnRadius||2)}buildSpawnSuggestions()};

function chooseNewCapital(p){if(!p?.cells?.size)return-1;let best=-1,bestScore=-1;const step=Math.max(1,Math.floor(p.cells.size/240));let k=0;for(const cell of p.cells){if((k++%step)!==0)continue;let support=0;for(const n of neighbors(cell))if(game.owner[n]===p.id)support++;const score=support*4+(game.cityByCell?.has(cell)?7:0)-((p.border.has(cell))?5:0)+sfHash(cell%game.GW,(cell/game.GW)|0,p.id);if(score>bestScore){bestScore=score;best=cell}}return best}
function handleCapitalCaptured(victimId,captorId,cell){const v=game.players[victimId],c=game.players[captorId];if(!v||v.capital!==cell)return;v.capital=-1;v.capitalLosses=(v.capitalLosses||0)+1;v.stability=clamp((v.stability??1)-.24,.35,1);v.warExhaustion=clamp((v.warExhaustion||0)+.14,0,1);v.balance*=.76;v.capitalRelocateAt=game.time+12;if(c){c.balance+=Math.min(900,Math.max(80,c.balance*.06));c.capitalsCaptured=(c.capitalsCaptured||0)+1;if(c.id===game.human)stats.capitalsCaptured=(stats.capitalsCaptured||0)+1}const text=c?`${c.name} captured ${v.name}'s capital`:`${v.name} lost its capital`;pushEvent(text,captorId===game.human?'good':victimId===game.human?'danger':'war',9);recordChronicle('capitalCapture',text+'.',{victim:victimId,captor:captorId,cell});soundEvent('capital');visualAudioCue('Capital captured','battle');if(victimId===game.human){flashNotice('CAPITAL LOST · economy disrupted');haptic([30,24,44])}if(captorId===game.human){flashNotice('Enemy capital captured');haptic([18,22,30])}registerWarEvent(victimId,captorId,'capitalCapture',cell)}
function handleCityChanged(city,old,newOwner){if(!city||old===newOwner)return;city.owner=newOwner;city.captures=(city.captures||0)+1;if(newOwner>=0&&old>=0&&newOwner!==old){const n=game.players[newOwner],v=game.players[old];const text=`${n.name} captured ${city.name} from ${v.name}`;if(newOwner===game.human||old===game.human||city.captures===1)pushEvent(text,newOwner===game.human?'good':old===game.human?'danger':'war',7);recordChronicle('cityCapture',text+'.',{city:city.id,cell:city.cell,from:old,to:newOwner});if(newOwner===game.human)stats.citiesCaptured=(stats.citiesCaptured||0)+1;soundEvent('city');registerWarEvent(old,newOwner,'cityCapture',city.cell)}}
const legacySetOwner=setOwner;
setOwner=function(i,newOwner,countCapture=true){const old=game.owner[i],wasCapital=old>=0&&game.players[old]?.capital===i,city=game.cityByCell?.get(i),oldCityOwner=city?.owner;legacySetOwner(i,newOwner,countCapture);if(wasCapital&&newOwner!==old)handleCapitalCaptured(old,newOwner,i);if(city&&newOwner!==oldCityOwner)handleCityChanged(city,oldCityOwner,newOwner)};

function updateStrategicGeography(dt){game.strategicAcc=(game.strategicAcc||0)+dt;if(game.strategicAcc<1)return;const step=game.strategicAcc;game.strategicAcc=0;game.supplyAcc=(game.supplyAcc||0)+step;if(game.supplyAcc>=3||!game.supplyReady){game.supplyAcc=0;const before=humanPlayer()?.supply??1;computeSupplyState();const me=humanPlayer();if(me&&before>=.70&&me.supply<.70&&game.time>(game.lastSupplyWarning||0)+12){game.lastSupplyWarning=game.time;pushEvent('Supply network is under strain','danger',7);visualAudioCue('Supply disrupted','battle')}}for(const p of game.players){if(!p.alive)continue;p.peakCells=Math.max(p.peakCells||0,p.cells.size);if(p.capital<0&&p.cells.size&&game.time>=p.capitalRelocateAt){const c=chooseNewCapital(p);if(c>=0){p.capital=c;p.stability=clamp((p.stability??.6)+.08,.35,1);const text=`${p.name} relocated its capital`;recordChronicle('capitalRelocate',text+'.',{nation:p.id,cell:c});if(p.id===game.human)pushEvent(text,'good',6)}}p.stability=clamp((p.stability??1)+.0025*step-(p.recentLoss>p.cells.size*.02?.002*step:0),.35,1);p.warExhaustion=clamp((p.warExhaustion||0)-.0016*step,0,1)}}
function drawStrategicMarkers(tr){if(game.cam.zoom<.72)return;ctx.save();for(const c of game.cities||[]){const x=tr.x+(c.cell%game.GW+.5)*tr.s,y=tr.y+(((c.cell/game.GW)|0)+.5)*tr.s;if(x<-12||x>viewW+12||y<-12||y>viewH+12)continue;const owner=game.owner[c.cell],col=owner>=0?game.players[owner]?.color:'#d7d5bf';ctx.fillStyle='#f4e5b9';ctx.strokeStyle=col||'#5b6e78';ctx.lineWidth=1.2;ctx.beginPath();ctx.rect(x-2.3,y-2.3,4.6,4.6);ctx.fill();ctx.stroke();if(game.cam.zoom>2.2&&prefs.showLabels){ctx.font='700 8px system-ui';ctx.textAlign='center';ctx.strokeStyle='rgba(0,0,0,.75)';ctx.lineWidth=2.5;ctx.strokeText(c.name,x,y+11);ctx.fillStyle='rgba(255,255,255,.96)';ctx.fillText(c.name,x,y+11)}}for(const p of game.players){if(!p.alive||p.capital<0||game.owner[p.capital]!==p.id)continue;const x=tr.x+(p.capital%game.GW+.5)*tr.s,y=tr.y+(((p.capital/game.GW)|0)+.5)*tr.s;if(x<-16||x>viewW+16||y<-16||y>viewH+16)continue;ctx.fillStyle='#fff4cf';ctx.strokeStyle='#122a3a';ctx.lineWidth=1.6;const r=game.cam.zoom>1.5?5:3.8;ctx.beginPath();ctx.moveTo(x,y-r);ctx.lineTo(x+r,y);ctx.lineTo(x,y+r);ctx.lineTo(x-r,y);ctx.closePath();ctx.fill();ctx.stroke()}ctx.restore()}
const legacyRenderGame=renderGame;renderGame=function(){legacyRenderGame();if(game.running)drawStrategicMarkers(getTransform())};
const legacyUpdateMinimap=updateMinimap;updateMinimap=function(){legacyUpdateMinimap();if(!prefs.showMinimap||!game.running)return;const sx=mini.width/game.GW,sy=mini.height/game.GH;mctx.save();for(const p of game.players){if(p.alive&&p.capital>=0){mctx.fillStyle='#fff';mctx.fillRect((p.capital%game.GW)*sx-1,(((p.capital/game.GW)|0))*sy-1,2,2)}}mctx.restore()};

// =============================================================================
// DIPLOMACY, NAMED WARS, AI MEMORY, CHRONICLE
// =============================================================================
function relationKey(a,b){return a<b?`${a}:${b}`:`${b}:${a}`}
function baseTrust(a,b){const pa=game.players[a],pb=game.players[b];if(!pa||!pb)return 50;return clamp(48+(pa.traits?.diplomacy||.5)*12+(pb.traits?.diplomacy||.5)*8+(gRandom()-.5)*18,18,82)}
function getRelation(a,b,create=true){if(a===b)return{state:'self',trust:100,rival:false};game.diplomacy ||= {};const k=relationKey(a,b);if(!game.diplomacy[k]&&create)game.diplomacy[k]={a:Math.min(a,b),b:Math.max(a,b),state:'peace',trust:baseTrust(a,b),rival:false,since:game.time||0,broken:0,lastChange:game.time||0};return game.diplomacy[k]||null}
function initDiplomacy(){game.diplomacy={};game.wars=[];game.warSeq=0;game.globalWar=false;game.globalWarStartedAt=0;game.watchlist=new Set();game.chronicle=[];game.timeline=[];game.lastChronicleLeader=-1;game.dipAcc=0;game.strategicWorldAcc=0}
function recordChronicle(type,text,data={}){if(!game.running||!text)return;game.chronicle ||= [];game.chronicle.push({time:+game.time||0,type,text,data});if(game.chronicle.length>260)game.chronicle.splice(0,game.chronicle.length-260)}
function warOrdinal(n){return['First','Second','Third','Fourth','Fifth'][n-1]||`${n}th`}
function makeWarName(a,b){const pa=game.players[a],pb=game.players[b],prev=(game.wars||[]).filter(w=>w.pair===relationKey(a,b)).length+1;if(prev===1)return`${pa.name}–${pb.name} War`;return`${warOrdinal(prev)} ${pa.name}–${pb.name} War`}
function activeWarBetween(a,b){return(game.wars||[]).find(w=>!w.ended&&w.pair===relationKey(a,b))||null}
function startWar(a,b,reason='border',forced=false){if(a<0||b<0||a===b||!game.players[a]?.alive||!game.players[b]?.alive)return false;const r=getRelation(a,b);if(r.state==='war')return true;if((r.state==='alliance'||r.state==='nap')&&!forced)return false;const betrayal=r.state==='alliance'||r.state==='nap';if(betrayal){r.broken=(r.broken||0)+1;r.trust=clamp(r.trust-48,0,100);game.players[b].traits.caution=clamp((game.players[b].traits.caution||.5)+.09,.08,.98);game.players[b].traits.vengeance=clamp((game.players[b].traits.vengeance||.45)+.12,.08,.98);recordChronicle('betrayal',`${game.players[a].name} broke its ${r.state==='alliance'?'alliance':'pact'} with ${game.players[b].name}.`,{a,b})}r.state='war';r.since=game.time;r.lastChange=game.time;r.trust=clamp(r.trust-16,0,100);const w={id:++game.warSeq,pair:relationKey(a,b),name:makeWarName(a,b),participants:[a,b],start:game.time,end:null,ended:false,reason,territoryExchanged:0,capitalCaptures:0,cityCaptures:0,navalOperations:0,initialCells:{[a]:game.players[a].cells.size,[b]:game.players[b].cells.size},winner:null,result:null};game.wars.push(w);const text=`${w.name} began`;pushEvent(text,a===game.human||b===game.human?'danger':'war',8);recordChronicle('warStart',text+'.',{warId:w.id,a,b});visualAudioCue('War declared','battle');soundEvent('attack',.75);return true}
function endWar(a,b,result='peace',winner=null){const r=getRelation(a,b,false),w=activeWarBetween(a,b);if(!r||r.state!=='war')return false;r.state='peace';r.since=game.time;r.lastChange=game.time;r.trust=clamp(r.trust+4,0,100);if(w){w.ended=true;w.end=game.time;w.result=result;w.winner=winner;const dur=Math.max(0,w.end-w.start);stats.longestWar=Math.max(stats.longestWar||0,dur);const text=winner!=null&&game.players[winner]?`${w.name} ended in victory for ${game.players[winner].name}`:`${w.name} ended`;recordChronicle('warEnd',text+'.',{warId:w.id,winner,result});pushEvent(text,'good',7);if(winner!=null&&game.players[winner])game.players[winner].warsWon=(game.players[winner].warsWon||0)+1;for(const pid of w.participants)if(pid!==winner&&game.players[pid])game.players[pid].warsLost=(game.players[pid].warsLost||0)+1}return true}
function formAlliance(a,b){if(a<0||b<0||a===b)return false;const r=getRelation(a,b);if(r.state==='war')return false;r.state='alliance';r.since=game.time;r.lastChange=game.time;r.trust=Math.max(r.trust,68);const text=`${game.players[a].name} and ${game.players[b].name} formed an alliance`;pushEvent(text,a===game.human||b===game.human?'good':'war',7);recordChronicle('alliance',text+'.',{a,b});if(a===game.human||b===game.human)stats.alliancesFormed=(stats.alliancesFormed||0)+1;soundEvent('open');visualAudioCue('Alliance formed','ui');return true}
function formNAP(a,b){const r=getRelation(a,b);if(!r||r.state==='war')return false;r.state='nap';r.since=game.time;r.lastChange=game.time;r.trust=Math.max(r.trust,55);const text=`${game.players[a].name} and ${game.players[b].name} signed a non-aggression pact`;recordChronicle('pact',text+'.',{a,b});if(a===game.human||b===game.human)pushEvent(text,'good',6);return true}
function breakAgreement(a,b){const r=getRelation(a,b);if(!r||!['alliance','nap'].includes(r.state))return false;const old=r.state;r.state='peace';r.lastChange=game.time;r.trust=clamp(r.trust-18,0,100);recordChronicle('breakPact',`${game.players[a].name} ended its ${old==='alliance'?'alliance':'pact'} with ${game.players[b].name}.`,{a,b});return true}
function declareRival(a,b){const r=getRelation(a,b);if(!r)return false;r.rival=!r.rival;r.trust=clamp(r.trust-(r.rival?8:-3),0,100);if(r.rival)recordChronicle('rivalry',`${game.players[a].name} and ${game.players[b].name} became strategic rivals.`,{a,b});return r.rival}
function diplomaticAttitude(a,b){const r=getRelation(a,b,false)||{state:'peace',trust:50,rival:false};if(r.state==='war')return'HOSTILE';if(r.state==='alliance')return'ALLY';if(r.state==='nap')return'PACT';if(r.rival)return'RIVAL';return r.trust>=68?'FRIENDLY':r.trust<=32?'SUSPICIOUS':'NEUTRAL'}
function registerWarEvent(a,b,type,cell=-1){if(a<0||b<0)return;const w=activeWarBetween(a,b);if(!w)return;if(type==='territory')w.territoryExchanged++;if(type==='capitalCapture')w.capitalCaptures++;if(type==='cityCapture')w.cityCaptures++;if(type==='naval')w.navalOperations++}
function relationBlocksAttack(a,b){if(b<0)return false;const r=getRelation(a,b);return r.state==='alliance'||r.state==='nap'}

const strategicSetOwner=setOwner;
setOwner=function(i,newOwner,countCapture=true){const old=game.owner[i];strategicSetOwner(i,newOwner,countCapture);if(old>=0&&newOwner>=0&&old!==newOwner){registerWarEvent(old,newOwner,'territory',i);const op=game.players[old],np=game.players[newOwner];if(op)op.warExhaustion=clamp((op.warExhaustion||0)+.00055,0,1);if(np)np.warExhaustion=clamp((np.warExhaustion||0)+.00018,0,1)}};
const legacyStartAttack=startAttack;
startAttack=function(attacker,defender,pct,quiet=false,targetCell=-1){if(defender>=0){const r=getRelation(attacker,defender);if(relationBlocksAttack(attacker,defender)){if(attacker===game.human&&!quiet)flashNotice(r.state==='alliance'?'Cannot attack an ally · end the alliance first':'Non-aggression pact is active');return false}const front=collectFrontSeeds(attacker,defender,targetCell,1);if(front.seeds.length&&r.state!=='war')startWar(attacker,defender,'border')}return legacyStartAttack(attacker,defender,pct,quiet,targetCell)};
const legacyStartNavalAttack=startNavalAttack;
startNavalAttack=function(attacker,defender,pct,targetCell,quiet=false,sourceOverride=-1){if(defender>=0){const r=getRelation(attacker,defender);if(relationBlocksAttack(attacker,defender)){if(attacker===game.human&&!quiet)flashNotice('Diplomatic agreement blocks this invasion');return false}const maxRange=navalRangeCells(),source=sourceOverride>=0?sourceOverride:nearestOwnedCell(attacker,targetCell,maxRange,true);if(source<0)return false;if(r.state!=='war')startWar(attacker,defender,'naval');registerWarEvent(attacker,defender,'naval',targetCell)}const ok=legacyStartNavalAttack(attacker,defender,pct,targetCell,quiet,sourceOverride);if(ok&&game.players[attacker])game.players[attacker].navalConfidence=clamp((game.players[attacker].navalConfidence||.45)+.006,.1,.95);return ok};
const legacyEvaluateContact=evaluateContact;
evaluateContact=function(pid,target,info,d){if(target>=0){const r=getRelation(pid,target);if(r.state==='alliance'||r.state==='nap')return-999;let score=legacyEvaluateContact(pid,target,info,d);if(r.state==='war')score+=12;else score-=clamp((r.trust-35)*.25,-6,13);if(r.rival)score+=8*(game.players[pid].traits?.vengeance||.5);return score}return legacyEvaluateContact(pid,target,info,d)};

function aiDiplomaticScore(a,b){const pa=game.players[a],pb=game.players[b],r=getRelation(a,b),threat=pb.cells.size/Math.max(1,pa.cells.size)+pb.balance/Math.max(1,pa.balance),commonThreat=game.lastLeader>=0&&game.lastLeader!==a&&game.lastLeader!==b&&(game.players[game.lastLeader]?.cells.size||0)>game.landCount*.15;return r.trust+(pa.traits?.diplomacy||.5)*22+(pa.traits?.loyalty||.5)*8-threat*5+(commonThreat?8:0)-(r.rival?24:0)}
function updateAIDiplomacy(dt){
  game.dipAcc=(game.dipAcc||0)+dt;if(game.dipAcc<3.2)return;const step=game.dipAcc;game.dipAcc=0;const alive=game.players.filter(p=>p.alive);
  for(const p of alive){if(p.id===game.human||p.freezeAI)continue;const contacts=[...(game.contacts[p.id]?.keys()||[])].filter(x=>x>=0&&game.players[x]?.alive);for(const qid of contacts.slice(0,6)){const r=getRelation(p.id,qid),q=game.players[qid];if(r.state==='war'){const w=activeWarBetween(p.id,qid),dur=w?game.time-w.start:0,ratio=p.balance/Math.max(1,q.balance),danger=p.cells.size<Math.max(10,q.cells.size*.35);if(dur>28&&((p.warExhaustion>.62&&ratio<.9)||danger)&&gRandom()<.16){endWar(p.id,qid,'negotiated',ratio>1.15?p.id:ratio<.78?qid:null);continue}}else if(r.state==='peace'&&game.time-r.lastChange>20){const sc=aiDiplomaticScore(p.id,qid);if(sc>78&&gRandom()<.035){formAlliance(p.id,qid);continue}if(sc>66&&gRandom()<.05)formNAP(p.id,qid)}else if(r.state==='alliance'){r.trust=clamp(r.trust+.025*step,0,100);p.traits.loyalty=clamp((p.traits.loyalty||.5)+.00025*step,.08,.98)}}
  }
}
function updateGlobalWar(){const alive=game.players.filter(p=>p.alive),active=(game.wars||[]).filter(w=>!w.ended),participants=new Set();for(const w of active)for(const p of w.participants)if(game.players[p]?.alive)participants.add(p);const now=alive.length>=6&&participants.size>=Math.max(5,Math.ceil(alive.length*.58))&&active.length>=Math.max(3,Math.floor(alive.length*.26));if(now&&!game.globalWar){game.globalWar=true;game.globalWarStartedAt=game.time;pushEvent('GLOBAL WAR · conflict now spans most surviving powers','danger',10);recordChronicle('globalWar','A global war engulfed most surviving powers.',{participants:[...participants]});visualAudioCue('Global war','battle')}else if(!now&&game.globalWar&&game.time-game.globalWarStartedAt>25){game.globalWar=false;recordChronicle('globalWarEnd','The global war fragmented into separate conflicts.',{})}}
function updateStrategicWorld(dt){game.strategicWorldAcc=(game.strategicWorldAcc||0)+dt;if(game.strategicWorldAcc<1.2)return;const step=game.strategicWorldAcc;game.strategicWorldAcc=0;updateAIDiplomacy(step);updateGlobalWar();for(const p of game.players){if(!p.alive)continue;const wars=(game.wars||[]).filter(w=>!w.ended&&w.participants.includes(p.id)).length;if(wars)p.warExhaustion=clamp((p.warExhaustion||0)+.0012*step*wars,0,1);if(p.recentLoss>p.cells.size*.05){p.traits.caution=clamp((p.traits.caution||.5)+.002*step,.08,.98);p.traits.aggression=clamp((p.traits.aggression||.5)-.001*step,.08,.98)}else if(p.recentGain>p.cells.size*.04){p.traits.ambition=clamp((p.traits.ambition||.5)+.001*step,.08,.98)}}const lead=strategicRankings()[0]?.id??-1;if(game.spawned&&game.time>15&&lead!==game.lastChronicleLeader){if(lead>=0)recordChronicle('leader',`${game.players[lead].name} became the world's largest power.`,{nation:lead});game.lastChronicleLeader=lead}}

const legacyHandleElimination=handleElimination;
handleElimination=function(victimId,killerId){legacyHandleElimination(victimId,killerId);const v=game.players[victimId],k=killerId>=0?game.players[killerId]:null;recordChronicle('elimination',k?`${k.name} eliminated ${v.name}.`:`${v.name} collapsed.`,{victim:victimId,killer:killerId});for(const w of game.wars||[]){if(!w.ended&&w.participants.includes(victimId)){const other=w.participants.find(x=>x!==victimId&&game.players[x]?.alive);if(other!=null)endWar(victimId,other,'elimination',other)}}};

function powerCategory(ratio){return ratio>=2.5?'OVERWHELMING':ratio>=1.55?'SUPERIOR':ratio>=1.16?'ADVANTAGE':ratio>=.86?'COMPARABLE':ratio>=.64?'DISADVANTAGE':ratio>=.40?'INFERIOR':'CRITICAL'}
function compareNationToPlayer(pid){const p=game.players[pid],me=humanPlayer();if(!p||!me)return{};const front=(game.contacts[me.id]?.get(pid)?.count||0)/(game.contacts[pid]?.get(me.id)?.count||1);return{territory:powerCategory(p.cells.size/Math.max(1,me.cells.size)),economy:powerCategory(growthRate(p)/Math.max(.01,growthRate(me))),reserves:powerCategory(p.balance/Math.max(1,me.balance)),front:powerCategory(front||1),naval:powerCategory((p.coast.size+1)/(me.coast.size+1)),stability:powerCategory((p.stability||.7)/(me.stability||.7))}}
function centerOnNation(pid,zoom=2){const p=game.players[pid];if(!p?.cells?.size)return;let sx=0,sy=0,n=0,step=Math.max(1,Math.floor(p.cells.size/300)),k=0;for(const c of p.cells){if((k++%step)!==0)continue;sx+=c%game.GW;sy+=(c/game.GW)|0;n++}if(!n)return;const wx=sx/n,wy=sy/n;setZoomFocus(wx,wy,viewW/2,viewH/2,Math.max(game.cam.zoom,zoom));game.cam.vx=game.cam.vy=0;game.dirty=true}

inspectNation=function(pid){const p=game.players[pid];if(!p)return;game.inspected=pid;drawAvatarCanvas($('#inspectAvatar'),p.avatar,p.avatarImage||'',p.color);$('#inspectName').textContent=p.name;const rank=Math.max(1,strategicRankings().findIndex(x=>x.id===pid)+1),pct=p.cells.size/Math.max(1,game.landCount)*100,trend=p.recentGain-p.recentLoss,rel=game.human>=0&&pid!==game.human?getRelation(game.human,pid):null,wars=(game.wars||[]).filter(w=>!w.ended&&w.participants.includes(pid)),traits=p.traits?Object.entries(p.traits).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([x])=>x.toUpperCase()).join(' · '):p.behavior.toUpperCase(),comp=compareNationToPlayer(pid);$('#inspectMeta').textContent=`${pid===game.human?'CONTROLLED · ':''}${p.doctrine||'Balanced'} · ${traits} · Rank #${rank}`;const relationText=rel?`${diplomaticAttitude(game.human,pid)} · Trust ${Math.round(rel.trust)}`:'SELF';$('#inspectStats').innerHTML=`<span>${fmt(p.balance)} reserves</span><span>${pct.toFixed(1)}% territory</span><span>+${fmt(growthRate(p))}/s economy</span><span>${p.capital>=0?'Capital secure':'CAPITAL LOST'}</span><span>${playerCityCount(pid)} strategic cities</span><span>Stability ${Math.round((p.stability||0)*100)}%</span><span>Supply ${supplyLabel(p)} · ${Math.round((p.supply??1)*100)}%</span><span>War exhaustion ${Math.round((p.warExhaustion||0)*100)}%</span><span>${wars.length} active war${wars.length===1?'':'s'}</span><span>${relationText}</span>${game.human>=0&&pid!==game.human?`<span>Power: ${comp.territory} land · ${comp.reserves} reserves</span>`:''}`;let acts=$('#nationInspect .inspectActions');if(!acts){acts=document.createElement('div');acts.className='inspectActions';$('#nationInspect .inspectCard').appendChild(acts)}acts.innerHTML=pid!==game.human?`<button data-inspect="focus">Focus</button><button data-inspect="watch">${game.watchlist?.has(pid)?'★ Watched':'☆ Watch'}</button>${game.human>=0?'<button data-inspect="dip">Diplomacy</button>':''}`:'<button data-inspect="focus">Capital</button>';acts.querySelector('[data-inspect="focus"]').onclick=()=>centerOnNation(pid);acts.querySelector('[data-inspect="watch"]')?.addEventListener('click',()=>{game.watchlist ||= new Set();game.watchlist.has(pid)?game.watchlist.delete(pid):game.watchlist.add(pid);inspectNation(pid);renderDiplomacy()});acts.querySelector('[data-inspect="dip"]')?.addEventListener('click',()=>{renderDiplomacy(pid);openModal('diplomacy')});$('#nationInspect').classList.add('open')};

function diplomaticAction(target,action){const me=game.human;if(me<0||target===me||!game.players[target]?.alive)return;const r=getRelation(me,target),ai=game.players[target],score=aiDiplomaticScore(target,me)+(r.trust-50)*.35;let accepted=false;if(action==='alliance'){accepted=r.state!=='war'&&score>62;accepted?formAlliance(me,target):pushEvent(`${ai.name} rejected your alliance proposal`,'war',6)}else if(action==='nap'){accepted=r.state!=='war'&&score>50;accepted?formNAP(me,target):pushEvent(`${ai.name} rejected the pact`,'war',6)}else if(action==='peace'){accepted=r.state==='war'&&((ai.warExhaustion||0)>.38||score>54||ai.cells.size<game.players[me].cells.size*.55);accepted?endWar(me,target,'negotiated',null):pushEvent(`${ai.name} rejected peace terms`,'war',6)}else if(action==='break'){breakAgreement(me,target);accepted=true}else if(action==='rival'){declareRival(me,target);accepted=true}else if(action==='war'){accepted=startWar(me,target,'declaration',true)}soundEvent(accepted?'open':'repel');renderDiplomacy(target)}
function renderDiplomacy(focus=-1){const list=$('#diplomacyList');if(!list||!game.running)return;const me=humanPlayer(),q=($('#nationSearchInput')?.value||'').trim().toLowerCase(),ranked=strategicRankings();let rows=ranked.filter(p=>p.id!==game.human&&p.alive);if(q)rows=rows.filter(p=>{const r=game.human>=0?getRelation(game.human,p.id):null;return p.name.toLowerCase().includes(q)||diplomaticAttitude(game.human,p.id).toLowerCase().includes(q)||(r?.rival&&q.includes('rival'))||(r?.state==='alliance'&&q.includes('ally'))||(r?.state==='war'&&q.includes('enemy'))});if(focus>=0)rows.sort((a,b)=>(a.id===focus?-1:b.id===focus?1:0));$('#diplomacySummary').textContent=me?`${me.name} · ${[...Object.values(game.diplomacy||{})].filter(r=>r.state==='alliance'&&(r.a===me.id||r.b===me.id)).length} allies · ${(game.wars||[]).filter(w=>!w.ended&&w.participants.includes(me.id)).length} wars · ${game.globalWar?'GLOBAL WAR ACTIVE':'regional diplomacy'}`:'Spectator intelligence view';list.innerHTML=rows.slice(0,45).map(p=>{const r=game.human>=0?getRelation(game.human,p.id):{state:'peace',trust:50},att=game.human>=0?diplomaticAttitude(game.human,p.id):'OBSERVE';return`<div class="dipRow" data-pid="${p.id}"><i class="dipFlag" style="background:${p.color}"></i><div class="dipInfo"><b>${game.watchlist?.has(p.id)?'★ ':''}${escapeHTML(p.name)}</b><small>#${ranked.findIndex(x=>x.id===p.id)+1} · ${att}${game.human>=0?' · Trust '+Math.round(r.trust):''} · ${p.doctrine}</small></div><div class="dipActions">${game.human>=0?(r.state==='war'?'<button class="dipAction good" data-act="peace">Offer Peace</button>':r.state==='alliance'||r.state==='nap'?'<button class="dipAction" data-act="break">End Agreement</button>':'<button class="dipAction good" data-act="alliance">Alliance</button><button class="dipAction" data-act="nap">NAP</button><button class="dipAction war" data-act="war">Declare War</button>')+'<button class="dipAction" data-act="rival">Rival</button>':''}<button class="dipAction" data-act="focus">Focus</button></div></div>`}).join('');list.querySelectorAll('.dipRow').forEach(row=>row.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{const pid=+row.dataset.pid;if(b.dataset.act==='focus'){centerOnNation(pid);closeAllModals()}else diplomaticAction(pid,b.dataset.act)}));const watch=$('#watchStrip');if(watch){watch.innerHTML=[...(game.watchlist||[])].filter(id=>game.players[id]?.alive).map(id=>`<button data-watch="${id}">★ ${escapeHTML(game.players[id].name)}</button>`).join('');watch.querySelectorAll('button').forEach(b=>b.onclick=()=>{centerOnNation(+b.dataset.watch);closeAllModals()})}}
function renderWarOverview(){const list=$('#warList');if(!list)return;const wars=(game.wars||[]).filter(w=>!w.ended).sort((a,b)=>a.start-b.start);$('#globalWarBanner').hidden=!game.globalWar;list.innerHTML=wars.length?wars.map(w=>{const [a,b]=w.participants.map(id=>game.players[id]);const da=(a?.cells.size||0)-(w.initialCells?.[a?.id]||0),db=(b?.cells.size||0)-(w.initialCells?.[b?.id]||0),state=Math.abs(da-db)<8?'EVEN':da>db?`${a?.name} ADVANTAGE`:`${b?.name} ADVANTAGE`;return`<div class="warRow"><i class="dipFlag" style="background:linear-gradient(135deg,${a?.color||'#777'} 0 50%,${b?.color||'#999'} 50%)"></i><div><b>${escapeHTML(w.name)}</b><small>${timeFmt(game.time-w.start)} · ${state} · ${w.territoryExchanged} cells exchanged · ${w.capitalCaptures} capitals</small></div><button class="dipAction" data-war="${w.id}">Focus</button></div>`}).join(''):'<div class="setupHint">No active wars. Borders are tense, but diplomacy still holds.</div>';list.querySelectorAll('[data-war]').forEach(b=>b.onclick=()=>{const w=game.wars.find(x=>x.id===+b.dataset.war),p=w&&game.players[w.participants[0]];if(p)centerOnNation(p.id);closeAllModals()})}

// =============================================================================
// GAME START, OPERATIONS OBJECTIVES, STRATEGIC AI, REPORTING
// =============================================================================
aiDifficulty=function(){const d=game.difficulty||prefs.difficulty;return{Easy:{interval:1.55,noise:28,mistake:.22,navalSamples:28,foresight:.62,threshold:18},Normal:{interval:1.02,noise:13,mistake:.09,navalSamples:48,foresight:1,threshold:10},Hard:{interval:.76,noise:6,mistake:.025,navalSamples:70,foresight:1.22,threshold:5},Insane:{interval:.56,noise:2,mistake:.005,navalSamples:96,foresight:1.42,threshold:1}}[d]||{interval:1.02,noise:13,mistake:.09,navalSamples:48,foresight:1,threshold:10}};

function beginObjective(){if(!game.rules?.operation){game.objective=null;return}const o=OPERATIONS[game.operationId];game.objective={...o.objectiveSpec,name:o.objective,complete:false,failed:false,startTime:game.time}}
function objectiveProgressText(){const o=game.objective,me=humanPlayer();if(!o||!me)return'';if(o.type==='survive')return`${timeFmt(Math.min(game.time,o.seconds))} / ${timeFmt(o.seconds)} · capital ${me.capitalLosses?'LOST':'secure'}`;if(o.type==='naval')return`${game.navalsSucceeded}/${o.landings} landings · ${(me.cells.size/game.landCount*100).toFixed(1)}%/${o.land}% land`;if(o.type==='capitalCapture')return`${me.capitalsCaptured||0}/${o.count} enemy capitals`;return''}
function updateObjective(){const o=game.objective,me=humanPlayer();if(!o||o.complete||o.failed||!me)return;if(o.type==='survive'){if(o.capitalRequired&&me.capitalLosses>0){o.failed=true;finishGame(false,'Operation failed — your capital fell.');return}if(game.time>=o.seconds)o.complete=true}else if(o.type==='naval'){o.complete=game.navalsSucceeded>=o.landings&&me.cells.size/game.landCount*100>=o.land}else if(o.type==='capitalCapture'){o.complete=(me.capitalsCaptured||0)>=o.count}if(o.complete)finishGame(true,'Primary objective complete.')}
