  game.mapId=prefs.map||'europe';game.map=MAPS[game.mapId]||MAPS.europe;pendingDeployment=game.operationId?{operationId:game.operationId}:pendingDeployment;game.rules=activeRules(modeId);game.difficulty=modeId==='operation'?OPERATIONS[game.operationId].difficulty:prefs.difficulty;const size=gridForMap(modeId,game.mapId);game.GW=size.w;game.GH=size.h;game.rng=(opts.seed??((Date.now()&0xffffffff)^((performance.now()*1000)|0)^game.GW*2654435761))>>>0||1;
  Object.assign(game,{running:true,paused:false,over:false,winner:false,human:game.rules.spectator?-1:0,spectator:!!game.rules.spectator,spawnLeft:game.rules.spectator?0:10,lastCountdown:10,spawned:!!game.rules.spectator,time:0,attacks:[],navals:[],fx:[],events:[],contacts:[],contactDirty:true,labels:[],captured:0,eliminations:0,attacksLaunched:0,navalsLaunched:0,navalsSucceeded:0,maxHumanPct:0,lastLeader:-1,announcedLeader:-1,leaderSince:0,lastHeavyWarning:0,simAcc:0,hudAcc:0,contactAcc:0,miniAcc:0,labelAcc:0,eventAcc:0,borderDirty:true,borderLast:0,pendingAttack:null,tutorialActive:!game.rules.spectator&&!game.rules.operation&&!prefs.tutorialSeen,tutorialStage:0,tutorialTimer:0,aiFrozen:false,sandboxEditing:false,sandboxPaint:null,sandboxSelected:1,sandboxIntel:false,inspected:-1,lastTarget:-1,strategicAcc:0,strategicWorldAcc:0,dipAcc:0,lastTimelineAt:-99,supplyAcc:0,supplyReady:false,lastSupplyWarning:-99});game.cam={zoom:1,panX:0,panY:0,vx:0,vy:0};game.attackPct=+$('#attackSlider').value;world.width=game.GW;world.height=game.GH;const br=borderResolution();borderWorld.width=game.GW*br;borderWorld.height=game.GH*br;
  generateMap();analyzeTopology();generateStrategicCities();createPlayers();initDiplomacy();spawnBots();rebuildAllBorders();rebuildContacts();assignStrategicColors();paintWholeWorld();redrawBorders();computeLabels();rebuildCityIndex();beginObjective();resizeCanvas();updateHUD(true);updateLeaderboard(true);updateMinimap();renderEventFeed();$('#pauseOverlay').classList.remove('open');$('#resultOverlay').classList.remove('open');$('#spawnOverlay').style.display=game.rules.spectator?'none':'block';$('#gameTimer').textContent=`${game.mode.name} · ${game.map.name}`;document.documentElement.classList.toggle('sandboxActive',!!game.rules.sandbox);document.documentElement.classList.remove('sandboxPainting','showTarget');closeInspection();$('#sandboxBar').classList.remove('open');applyLiveSettings();applyMajorPreferences();updateAttackControls();syncMusic();if(game.tutorialActive)showCoach('<b>1/4 · Establish</b> Choose highlighted land with room to expand.');else hideCoach();
  const opening=game.rules.spectator?`World simulation began in ${game.map.name}.`:`${prefs.name} entered the ${game.map.name} theater.`;recordChronicle('start',opening,{map:game.mapId,mode:modeId,seed:game.rng});pushEvent(game.rules.spectator?`Spectator · ${game.map.name} · ${game.difficulty}`:`${game.mode.name} · ${game.map.name} · ${game.difficulty}`,'good',5);game.lastTS=performance.now();game.lastRenderTS=game.lastTS;if(game.rafId)cancelAnimationFrame(game.rafId);game.rafId=requestAnimationFrame(loop)
