// Strategic AI goals are medium-term preferences, not hard scripts.
function refreshStrategicGoal(p){if(!p.alive||p.id===game.human)return;const current=p.strategicGoal;if(current&&game.time<current.until&&(!current.target||game.players[current.target]?.alive))return;const reserve=desiredReserve(p),leader=strategicRankings()[0];let goal={type:'expand',target:NEUTRAL,until:game.time+gRand(16,8)};if(p.capital<0||p.balance<reserve*.55||p.warExhaustion>.72||(p.supply??1)<.58)goal={type:'rebuild',target:null,until:game.time+gRand(18,10)};else if(p.traits?.naval>.68&&p.coast.size>4&&p.components.size<2)goal={type:'naval',target:null,until:game.time+gRand(22,12)};else if(leader&&leader.id!==p.id&&leader.cells.size>game.landCount*.16&&p.traits?.ambition>.5)goal={type:'containLeader',target:leader.id,until:game.time+gRand(24,14)};else if(p.lastAttacker>=0&&game.time-p.lastAttackedAt<30&&p.traits?.vengeance>.55)goal={type:'rival',target:p.lastAttacker,until:game.time+gRand(22,10)};p.strategicGoal=goal}
const diplomacyEvaluateContact=evaluateContact;
evaluateContact=function(pid,target,info,d){let score=diplomacyEvaluateContact(pid,target,info,d),p=game.players[pid];refreshStrategicGoal(p);const g=p.strategicGoal;if(g?.type==='rebuild'&&target!==NEUTRAL)score-=24;if(g?.type==='expand'&&target===NEUTRAL)score+=9;if(g?.type==='containLeader'&&target===g.target)score+=16;if(g?.type==='rival'&&target===g.target)score+=12;if(target>=0){const e=game.players[target],r=getRelation(pid,target);const ourWars=(game.wars||[]).filter(w=>!w.ended&&w.participants.includes(pid)).length,targetAllies=Object.values(game.diplomacy||{}).filter(x=>x.state==='alliance'&&(x.a===target||x.b===target)).length;score-=ourWars*4;score-=targetAllies*3.5;score-=Math.max(0,(p.warExhaustion||0)-.45)*24;if(r.state==='peace'&&p.traits?.diplomacy>.7)score-=5;if(e?.capital>=0&&info?.count>2&&p.traits?.ambition>.65)score+=4}return score};
const legacyThinkOneAI=thinkOneAI;
thinkOneAI=function(p){refreshStrategicGoal(p);if(p.freezeAI)return;if(p.strategicGoal?.type==='rebuild'&&p.balance<desiredReserve(p)*.9){if(p.attacks>0)cancelOneAttack(p.id);return}if(p.capital<0&&p.balance<desiredReserve(p)*.8){if(p.attacks>0)cancelOneAttack(p.id);return}legacyThinkOneAI(p)};

