function buildReportData(win,sub){const me=humanPlayer()||game.players[0],ranked=strategicRankings(),rank=me?Math.max(1,ranked.findIndex(p=>p.id===me.id)+1):0,land=me?me.cells.size/game.landCount*100:0,activeWars=(game.wars||[]).filter(w=>w.participants.includes(me?.id)),longest=activeWars.sort((a,b)=>((b.end||game.time)-b.start)-((a.end||game.time)-a.start))[0];return{win,sub,mode:game.mode.name,map:game.map.name,difficulty:game.difficulty,seed:game.rng,time:game.time,nation:me?.name||'Spectator',rank,land,peak:Math.max(game.maxHumanPct||0,land),troops:me?.balance||0,elims:me?.elims||0,attacks:game.attacksLaunched,naval:[game.navalsSucceeded,game.navalsLaunched],captured:game.captured,capitals:me?.capitalsCaptured||0,cities:playerCityCount(me?.id??-1),wars:activeWars.length,longestWar:longest?longest.name:'—',chronicle:[...(game.chronicle||[])],timeline:[...(game.timeline||[])],operationId:game.operationId,rating:operationRating()}}
const legacyFinishGame=finishGame;
finishGame=function(win,sub){if(game.over)return;recordChronicle(win?'victory':'defeat',win?`${humanPlayer()?.name||'The player'} achieved victory.`:`${humanPlayer()?.name||'The player'} was defeated.`,{});lastReport=buildReportData(win,sub);legacyFinishGame(win,sub);clearActiveBattle();if(game.operationId){const rating=lastReport.rating||'FAILED';const old=stats.operations[game.operationId]||{};const order={FAILED:0,BRONZE:1,SILVER:2,GOLD:3,SOVEREIGN:4};if((order[rating]||0)>(order[old.best]||0))stats.operations[game.operationId]={best:rating,time:game.time,date:Date.now()};$('#resultSub').textContent=`${sub} · Operation rating: ${rating}`}stats.chronicles=[{date:Date.now(),nation:lastReport.nation,map:lastReport.map,result:win?'Victory':'Defeat',chronicle:lastReport.chronicle.slice(-120)},...(stats.chronicles||[])].slice(0,10);saveStats();updateContinueCampaignCard()};
function renderCampaignReport(){const r=lastReport;if(!r){$('#reportSummary').innerHTML='<div class="setupHint">No completed campaign report is available.</div>';return}$('#reportSummary').innerHTML=`<div class="reportStatsGrid"><div class="reportStat"><span>FINAL RANK</span><b>#${r.rank}</b></div><div class="reportStat"><span>TERRITORY</span><b>${r.land.toFixed(1)}%</b></div><div class="reportStat"><span>PEAK TERRITORY</span><b>${r.peak.toFixed(1)}%</b></div><div class="reportStat"><span>ELIMINATIONS</span><b>${r.elims}</b></div><div class="reportStat"><span>CAPITALS TAKEN</span><b>${r.capitals}</b></div><div class="reportStat"><span>NAVAL LANDINGS</span><b>${r.naval[0]}/${r.naval[1]}</b></div><div class="reportStat"><span>LONGEST WAR</span><b style="font-size:12px">${escapeHTML(r.longestWar)}</b></div><div class="reportStat"><span>SEED</span><b style="font-size:12px">${(r.seed>>>0).toString(16).toUpperCase()}</b></div></div>${r.rating?`<div class="briefObjective"><span>OPERATION RATING</span><b>${r.rating}</b></div>`:''}`;$('#reportChronicle').innerHTML=r.chronicle.length?r.chronicle.map(e=>`<div class="chronicleEntry"><time>${timeFmt(e.time)}</time><p>${escapeHTML(e.text)}</p></div>`).join(''):'<div class="setupHint">No major events were recorded.</div>';drawTimelineReport()}
function drawTimelineReport(){const cv=$('#timelineCanvas');if(!cv||!lastReport)return;const c=cv.getContext('2d'),d=lastReport.timeline;c.clearRect(0,0,cv.width,cv.height);c.fillStyle='#eaf1f5';c.fillRect(0,0,cv.width,cv.height);if(d.length<2){c.fillStyle='#5e7888';c.font='16px system-ui';c.fillText('Not enough timeline data',24,42);return}const pad=42,w=cv.width-pad*2,h=cv.height-pad*2,maxT=d[d.length-1].t||1;c.strokeStyle='#c4d3dc';c.lineWidth=1;for(let i=0;i<=4;i++){const y=pad+h*i/4;c.beginPath();c.moveTo(pad,y);c.lineTo(pad+w,y);c.stroke()}const draw=(key,max,col)=>{c.strokeStyle=col;c.lineWidth=3;c.beginPath();d.forEach((v,i)=>{const x=pad+v.t/maxT*w,y=pad+h-(clamp(v[key],0,max)/max)*h;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()};draw('land',100,'#1b719d');const maxTroops=Math.max(...d.map(x=>x.troops),1);draw('troops',maxTroops,'#b1854c');c.fillStyle='#405f71';c.font='12px system-ui';c.fillText('Territory %',pad,20);c.fillStyle='#b1854c';c.fillText('Troop reserve',pad+96,20)}

