checkEndConditions=function(){if(game.rules?.sandbox||game.rules?.spectator)return;const me=humanPlayer();if(!me)return;if(game.spawned&&me.cells.size===0){finishGame(false,'Your nation was eliminated.');return}if(game.rules?.operation){if(game.rules.timeLimit&&game.time>=game.rules.timeLimit)finishGame(false,'Operation time expired.');return}const alive=game.players.filter(p=>p.alive&&p.cells.size>0);if(me.cells.size>game.landCount*(game.rules.victory/100)){finishGame(true,`You control ${game.rules.victory}% of the map.`);return}if(alive.length===1&&alive[0].id===me.id){finishGame(true,'You are the last nation standing.');return}if(game.rules.timeLimit&&game.time>=game.rules.timeLimit){const ranked=strategicRankings(),rank=ranked.findIndex(p=>p.id===me.id)+1;finishGame(rank===1,rank===1?'Time expired — you hold the most land.':'Time expired. Largest territory wins.')}};
// Do not create a diplomatic war during the pre-war grace period.
const dipStartAttack=startAttack;startAttack=function(attacker,defender,pct,quiet=false,targetCell=-1){if(defender>=0&&game.time<(game.rules.peacefulStart||0))return dipStartAttack(attacker,defender,pct,quiet,targetCell);return dipStartAttack(attacker,defender,pct,quiet,targetCell)};
// The wrapper above intentionally delegates; startWar is guarded below by temporarily preserving peace.
// Patch declaration behavior precisely by wrapping startWar itself.
const rawStartWar=startWar;startWar=function(a,b,reason='border',forced=false){if(!forced&&game.time<(game.rules?.peacefulStart||0))return false;return rawStartWar(a,b,reason,forced)};

// Richer event sounds and visual-audio captions without adding copyrighted assets.
const legacySoundEvent=soundEvent;
soundEvent=function(name,intensity=1){
  const custom={capital:()=>{tone(156,.24,'triangle',.060,0,'battle',260);tone(392,.28,'sine',.035,.08,'battle');noise(.13,.025,.02,720)},city:()=>{tone(330,.09,'triangle',.025,0,'battle',470);tone(520,.12,'sine',.020,.05,'battle')},alliance:()=>{tone(392,.10,'sine',.028,0,'ui');tone(523,.13,'triangle',.024,.055,'ui');tone(659,.16,'sine',.018,.10,'ui')},betrayal:()=>{tone(220,.16,'sawtooth',.035,0,'battle',120);tone(146,.24,'sine',.028,.08,'battle')},globalWar:()=>{tone(82,.34,'sawtooth',.040,0,'battle',62);noise(.22,.026,.02,480);tone(164,.32,'triangle',.025,.11,'battle')},peace:()=>{tone(330,.14,'sine',.024,0,'ui',440);tone(494,.18,'triangle',.018,.08,'ui')}};
  if(custom[name])custom[name]();else legacySoundEvent(name,intensity);
  const captions={attack:'Land offensive',naval:'Naval launch',land:'Beachhead secured',repel:'Offensive repelled',eliminate:'Nation eliminated',capital:'Capital captured',city:'Strategic city captured',alliance:'Alliance formed',betrayal:'Alliance broken',globalWar:'Global war',win:'Victory',lose:'Defeat',damage:'Territory under attack'};if(captions[name])visualAudioCue(captions[name],name==='tap'?'ui':'battle')
};

function strategicMusicState(){if(!game.running||game.over)return'menu';const me=humanPlayer(),active=(game.wars||[]).filter(w=>!w.ended).length;if(game.globalWar)return'global';if(me){const share=me.cells.size/Math.max(1,game.landCount),under=me.recentLoss>Math.max(8,me.cells.size*.04);if(share>.43)return'nearVictory';if(under||me.capital<0)return'underAttack'}if(active>=Math.max(4,game.players.filter(p=>p.alive).length*.18))return'major';if(active>0)return'regional';return'peace'}
musicTick=function(){if(!prefs.sound||!prefs.music||!audioCtx)return;const st=strategicMusicState(),cfg={menu:{roots:[110,123.47,146.83,164.81],gap:[3.2,4.8],vol:.017},peace:{roots:[87.31,98,110,130.81],gap:[3.0,4.5],vol:.016},regional:{roots:[82.41,98,110,123.47],gap:[2.1,3.2],vol:.020},major:{roots:[73.42,82.41,98,110],gap:[1.45,2.2],vol:.023},underAttack:{roots:[65.41,73.42,87.31],gap:[1.15,1.75],vol:.026},global:{roots:[55,65.41,73.42,82.41],gap:[.92,1.42],vol:.029},nearVictory:{roots:[98,123.47,146.83,196],gap:[1.6,2.5],vol:.024}}[st]||null,root=cfg.roots[musicPhase%cfg.roots.length],gap=gRand(cfg.gap[1],cfg.gap[0]);musicPhase++;tone(root,gap+.7,'sine',cfg.vol,0,'music');tone(root*(musicPhase%2?1.5:1.333),Math.min(1.7,gap*.7),'triangle',cfg.vol*.48,.14,'music');if(['major','underAttack','global'].includes(st)){tone(root*.5,.22,'triangle',cfg.vol*.7,.02,'music');if(musicPhase%2===0)noiseMusicPulse(root,gap,cfg.vol)}if(st==='nearVictory'&&musicPhase%3===0)tone(root*2,.65,'sine',cfg.vol*.4,.45,'music');musicTimer=setTimeout(musicTick,gap*1000)};
function noiseMusicPulse(root,gap,vol){if(!ensureAudio())return;const now=audioCtx.currentTime+.06,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=Math.max(42,root*.55);g.gain.setValueAtTime(Math.max(.0001,vol*.26),now);g.gain.exponentialRampToValueAtTime(.0001,now+.18);o.connect(g);g.connect(musicGain);o.start(now);o.stop(now+.2)}

const sfStrategicUpdateHUD=updateHUD;
updateHUD=function(){sfStrategicUpdateHUD();const me=humanPlayer();if(!me||game.lastTarget>=0)return;if((me.supply??1)<.72){const el=$('#frontStatus');if(el)el.textContent=`SUPPLY ${supplyLabel(me)} · ${Math.round((me.supply??1)*100)}% connected · consolidate or secure a city`}};

// More contextual minimap: capitals, selected nation, navals and viewport remain visible.
const strategicMinimap=updateMinimap;updateMinimap=function(){strategicMinimap();if(!prefs.showMinimap||!game.running)return;const sx=mini.width/game.GW,sy=mini.height/game.GH;mctx.save();for(const n of game.navals||[]){const x=((n.from%game.GW)*(1-n.progress)+(n.to%game.GW)*n.progress)*sx,y=((((n.from/game.GW)|0)*(1-n.progress)+((n.to/game.GW)|0)*n.progress))*sy;mctx.fillStyle='#fff';mctx.fillRect(x-1,y-1,2,2)}if(game.inspected>=0){const p=game.players[game.inspected];if(p?.capital>=0){mctx.strokeStyle='#ffdc8a';mctx.lineWidth=2;mctx.strokeRect((p.capital%game.GW)*sx-3,(((p.capital/game.GW)|0))*sy-3,6,6)}}mctx.restore()};

