// Accessibility toggle state must remain visually synchronized.
const legacyRenderToggles=renderToggles;renderToggles=function(){legacyRenderToggles();for(const [id,key] of [['#reducedMotionToggle','reducedMotion'],['#reducedFlashingToggle','reducedFlashing'],['#highContrastToggle','highContrast'],['#visualAudioToggle','visualAudio'],['#leftHandedToggle','leftHanded']])$(id)?.classList.toggle('on',!!prefs[key]);applyMajorPreferences()};

