function pushSandboxUndo(action){game.sandboxUndo ||= [];game.sandboxRedo=[];game.sandboxUndo.push(action);if(game.sandboxUndo.length>36)game.sandboxUndo.shift()}
function refreshAfterSandboxOwnership(){for(const p of game.players){p.cells=new Set();p.border=new Set();p.coast=new Set();p.components=new Map();p.attacks=0}for(let i=0;i<game.owner.length;i++){const o=game.owner[i];if(o>=0&&game.players[o]){const p=game.players[o];p.cells.add(i);const cid=game.componentId[i];if(cid>=0)p.components.set(cid,(p.components.get(cid)||0)+1)}}for(const p of game.players){p.alive=p.cells.size>0;if(!p.alive){p.capital=-1;continue}if(p.capital<0||game.owner[p.capital]!==p.id)p.capital=chooseNewCapital(p)}rebuildAllBorders();rebuildContacts();rebuildCityIndex();computeSupplyState();paintWholeWorld();computeLabels();game.dirty=true;game.borderDirty=true;refreshSandboxNationList();updateHUD(true);updateLeaderboard(true)}
function applySandboxAction(action,redo=false){if(!action)return;if(action.type==='owners'){for(const c of action.cells)game.owner[c.i]=redo?c.new:c.old;refreshAfterSandboxOwnership()}else if(action.type==='capital'){const p=game.players[action.pid];if(p)p.capital=redo?action.new:action.old;game.dirty=true}else if(action.type==='cityAdd'){if(redo)game.cities.push({...action.city});else game.cities=game.cities.filter(c=>c.id!==action.city.id);rebuildCityIndex();game.dirty=true}else if(action.type==='cityRemove'){if(redo)game.cities=game.cities.filter(c=>c.id!==action.city.id);else game.cities.push({...action.city});rebuildCityIndex();game.dirty=true}}
function sandboxUndo(){const a=game.sandboxUndo?.pop();if(!a)return flashNotice('Nothing to undo');applySandboxAction(a,false);game.sandboxRedo.push(a);flashNotice('Sandbox edit undone')}
function sandboxRedo(){const a=game.sandboxRedo?.pop();if(!a)return flashNotice('Nothing to redo');applySandboxAction(a,true);game.sandboxUndo.push(a);flashNotice('Sandbox edit restored')}

const oldArmSandboxPaint=armSandboxPaint;
armSandboxPaint=function(mode,pid=game.sandboxSelected){oldArmSandboxPaint(mode,pid);const labels={capital:'MOVE CAPITAL',city:'PLACE STRATEGIC CITY',removeCity:'REMOVE STRATEGIC CITY'};if(labels[mode])$('#sandboxBarText').textContent=labels[mode]};

sandboxPaintCell=function(cell){
  if(!game.rules?.sandbox||!game.sandboxPaint||cell<0||game.owner[cell]===WATER)return;const {mode,pid}=game.sandboxPaint;
  if(mode==='capital'){const p=game.players[pid];if(!p?.alive||game.owner[cell]!==pid){flashNotice('Capital must be placed inside the selected nation');return}pushSandboxUndo({type:'capital',pid,old:p.capital,new:cell});p.capital=cell;p.capitalRelocateAt=0;game.sandboxEditing=false;game.sandboxPaint=null;$('#sandboxBar').classList.remove('open');document.documentElement.classList.remove('sandboxPainting');$('#pauseOverlay').classList.add('open');flashNotice(`${p.name} capital moved`);game.dirty=true;return}
  if(mode==='city'){if(game.cityByCell?.has(cell)){flashNotice('A strategic city already exists here');return}const city={id:Date.now()%100000000,cell,name:`Strategic Point ${(game.cities?.length||0)+1}`,owner:game.owner[cell],captures:0};pushSandboxUndo({type:'cityAdd',city:{...city}});game.cities.push(city);rebuildCityIndex();game.sandboxEditing=false;game.sandboxPaint=null;$('#sandboxBar').classList.remove('open');document.documentElement.classList.remove('sandboxPainting');$('#pauseOverlay').classList.add('open');flashNotice('Strategic city placed');game.dirty=true;return}
  if(mode==='removeCity'){const city=game.cityByCell?.get(cell);if(!city){flashNotice('Tap directly on a strategic city');return}pushSandboxUndo({type:'cityRemove',city:{...city}});game.cities=game.cities.filter(c=>c!==city);rebuildCityIndex();game.sandboxEditing=false;game.sandboxPaint=null;$('#sandboxBar').classList.remove('open');document.documentElement.classList.remove('sandboxPainting');$('#pauseOverlay').classList.add('open');flashNotice('Strategic city removed');game.dirty=true;return}
  if(mode==='spawn'){if(game.owner[cell]!==NEUTRAL){flashNotice('Choose neutral land to spawn this nation');return}const p=game.players[pid];const cx=cell%game.GW,cy=(cell/game.GW)|0,r=game.rules.spawnRadius||2,cells=[];for(let y=Math.max(0,cy-r);y<=Math.min(game.GH-1,cy+r);y++)for(let x=Math.max(0,cx-r);x<=Math.min(game.GW-1,cx+r);x++){if((x-cx)**2+(y-cy)**2>r*r+1)continue;const i=y*game.GW+x;if(game.owner[i]===NEUTRAL)cells.push({i,old:NEUTRAL,new:pid})}pushSandboxUndo({type:'owners',cells});for(const c of cells)game.owner[c.i]=pid;p.balance=Math.max(p.balance,game.rules.startTroops);p.alive=true;p.capital=cell;refreshAfterSandboxOwnership();game.sandboxPaint=null;game.sandboxEditing=false;document.documentElement.classList.remove('sandboxPainting');$('#sandboxBar').classList.remove('open');$('#pauseOverlay').classList.add('open');flashNotice(`${p.name} deployed`);return}
  const target=mode==='neutral'?NEUTRAL:pid,cx=cell%game.GW,cy=(cell/game.GW)|0,r=game.sandboxBrush||2,changes=[];for(let y=Math.max(0,cy-r);y<=Math.min(game.GH-1,cy+r);y++)for(let x=Math.max(0,cx-r);x<=Math.min(game.GW-1,cx+r);x++){if((x-cx)**2+(y-cy)**2>r*r)continue;const i=y*game.GW+x;if(game.owner[i]===WATER||game.owner[i]===target)continue;changes.push({i,old:game.owner[i],new:target})}if(!changes.length)return;pushSandboxUndo({type:'owners',cells:changes});for(const c of changes)game.owner[c.i]=c.new;refreshAfterSandboxOwnership()
};

const baseOpenSandboxTools=openSandboxTools;
openSandboxTools=function(){baseOpenSandboxTools();const p=selectedSandboxNation();if($('#sbExactTroops'))$('#sbExactTroops').value=Math.round(p?.balance||0);if($('#sbDoctrine'))$('#sbDoctrine').value=p?.doctrine||'Balanced';if($('#sbPersonality'))$('#sbPersonality').value=p?.behavior==='human'?(p.baseBehavior||'opportunist'):(p?.behavior||'opportunist');if($('#freezeSelectedBtn'))$('#freezeSelectedBtn').textContent=p?.freezeAI?'Unfreeze Selected':'Freeze Selected';if($('#sbAttackSpeed')){$('#sbAttackSpeed').value=Math.round((game.rules.attackSpeed||1)*100);$('#sbAttackValue').textContent=(game.rules.attackSpeed||1).toFixed(1)+'×'}};
function bindExtendedSandbox(){
  if(bindExtendedSandbox.done)return;bindExtendedSandbox.done=true;
  $('#sbSetTroopsBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation(),v=clamp(+$('#sbExactTroops').value||0,0,999999999);if(!p)return;p.balance=v;flashNotice(`${p.name}: ${fmt(v)} troops`);soundEvent('tap')});
  $('#freezeSelectedBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation();if(!p)return;p.freezeAI=!p.freezeAI;$('#freezeSelectedBtn').textContent=p.freezeAI?'Unfreeze Selected':'Freeze Selected';flashNotice(`${p.name} AI ${p.freezeAI?'frozen':'active'}`)});
  $('#sbDoctrine')?.addEventListener('change',e=>{const p=selectedSandboxNation();if(p){p.doctrine=e.target.value;flashNotice(`${p.name}: ${p.doctrine} doctrine`)}});
  $('#sbPersonality')?.addEventListener('change',e=>{const p=selectedSandboxNation();if(p){p.behavior=e.target.value;p.baseBehavior=e.target.value;p.traits=traitsForBehavior(e.target.value);flashNotice(`${p.name}: ${e.target.value} personality`)}});
  $('#moveCapitalBtn')?.addEventListener('click',()=>armSandboxPaint('capital',game.sandboxSelected));$('#placeCityBtn')?.addEventListener('click',()=>armSandboxPaint('city',game.sandboxSelected));$('#removeCityBtn')?.addEventListener('click',()=>armSandboxPaint('removeCity',game.sandboxSelected));
  $('#sbAllianceBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation(),me=humanPlayer();if(p&&me&&p.id!==me.id){const r=getRelation(p.id,me.id);if(r.state==='war')endWar(p.id,me.id,'editor',null);formAlliance(p.id,me.id);renderDiplomacy()}});
  $('#sbPeaceBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation(),me=humanPlayer();if(p&&me&&p.id!==me.id){const r=getRelation(p.id,me.id);if(r.state==='war')endWar(p.id,me.id,'editor',null);else{r.state='peace';r.lastChange=game.time}flashNotice('Relationship set to peace')}});
  $('#sbWarBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation(),me=humanPlayer();if(p&&me&&p.id!==me.id){breakAgreement(p.id,me.id);startWar(p.id,me.id,'sandbox',true);flashNotice('War forced')}});
  $('#sbRivalBtn')?.addEventListener('click',()=>{const p=selectedSandboxNation(),me=humanPlayer();if(p&&me&&p.id!==me.id){declareRival(p.id,me.id);flashNotice('Rivalry toggled')}});
  $('#sbAttackSpeed')?.addEventListener('input',e=>{game.rules.attackSpeed=+e.target.value/100;$('#sbAttackValue').textContent=game.rules.attackSpeed.toFixed(1)+'×';soundEvent('slider')});
  $('#sbUndoBtn')?.addEventListener('click',sandboxUndo);$('#sbRedoBtn')?.addEventListener('click',sandboxRedo);
  $('#sbManualSaveBtn')?.addEventListener('click',()=>{const save=buildBattleSave('sandbox-manual');if(!save)return;const arr=sfLoad(SF_EDITOR_SAVES)||[];arr.unshift(save);sfStore(SF_EDITOR_SAVES,arr.slice(0,3));flashNotice('Sandbox manual save created')});
  $('#sbManualLoadBtn')?.addEventListener('click',()=>{const arr=sfLoad(SF_EDITOR_SAVES)||[];if(!arr.length)return flashNotice('No manual Sandbox save');restoreBattleState(arr[0]);flashNotice('Sandbox save loaded')});
  $('#sandboxNation')?.addEventListener('change',()=>setTimeout(openSandboxTools,0));
}
setTimeout(bindExtendedSandbox,0);
